INSERT INTO sz_slowo_na_dzis (data, cytat, sigla_cytatu, czytania) VALUES
('2026-11-23', 'Prawdziwie powiadam wam: ta uboga wdowa wrzuciła więcej niż wszyscy inni', 'Łk 21, 3', '[{"nazwa": "I czytanie", "sigla": "Ap 14, 1-3. 4b-5"}, {"nazwa": "Psalm", "sigla": "Ps 24 (23)"}, {"nazwa": "Ewangelia", "sigla": "Łk 21, 1-4"}]'::jsonb),
('2026-11-25', 'Ale włos z głowy wam nie spadnie', 'Łk 21, 18', '[{"nazwa": "I czytanie", "sigla": "Ap 15, 1-4"}, {"nazwa": "Ewangelia", "sigla": "Łk 21, 12-19"}]'::jsonb),
('2026-11-26', '…zbliża się wasze odkupienie', 'Łk 21, 28', '[{"nazwa": "I czytanie", "sigla": "Ap 18, 1-2. 21-23; 19, 1-3. 9a"}, {"nazwa": "Ewangelia", "sigla": "Łk 21, 20-28"}]'::jsonb),
('2026-11-27', 'Niebo i ziemia przeminą, ale moje słowa nie przeminą', 'Łk 21, 33', '[{"nazwa": "I czytanie", "sigla": "Ap 20, 1-4. 11 – 21, 2"}, {"nazwa": "Ewangelia", "sigla": "Łk 21, 29-33"}]'::jsonb),
('2026-11-28', 'Czuwajcie więc i módlcie się w każdym czasie', 'Łk 21, 36', '[{"nazwa": "I czytanie", "sigla": "Ap 22, 1-7"}, {"nazwa": "Ewangelia", "sigla": "Łk 21, 34-36"}]'::jsonb),
('2026-11-29', 'Uważajcie, czuwajcie, bo nie wiecie, kiedy czas ten nadejdzie', 'Mk 13, 33', '[{"nazwa": "I czytanie", "sigla": "Iz 63, 16b-17. 19b; 64, 2b-7"}, {"nazwa": "II czytanie", "sigla": "1 Kor 1, 3-9"}, {"nazwa": "Ewangelia", "sigla": "Mk 13, 33-37"}]'::jsonb),
('2026-11-30', 'Pójdźcie za Mną, a uczynię was rybakami ludzi', 'Mt 4, 19', '[{"nazwa": "I czytanie", "sigla": "Iz 49, 1-6"}, {"nazwa": "Ewangelia", "sigla": "Mt 4, 18-22"}]'::jsonb);
INSERT INTO sz_obrzedy (id, kolejnosc, zakladka, skrot, tytul, wstep) VALUES ('zwykly', 1, 'Zwykły obrzęd', 'Zwykły', 'Zwykły obrzęd Komunii Chorych udzielanej przez nadzwyczajnego szafarza', '');
INSERT INTO sz_obrzedy_kroki (obrzed_id, nr, sekcja, tytul, bloki) VALUES
('zwykly', 1, 'Obrzędy wstępne', 'Pozdrowienie', '[{"t": "l", "w": "S", "x": "Pokój temu domowi i wszystkim jego mieszkańcom."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Niech będzie pochwalony Jezus Chrystus."}, {"t": "l", "w": "W", "x": "Na wieki wieków. Amen."}]'::jsonb),
('zwykly', 2, 'Obrzędy wstępne', 'Adoracja', '[{"t": "r", "x": "Następnie szafarz składa Najświętszy Sakrament na stole i adoruje Go razem z obecnymi w ciszy albo odmawiając odpowiednią modlitwę, np.:"}, {"t": "l", "w": "", "x": "O święta Uczto, na której przyjmujemy Chrystusa, odnawiamy pamięć Jego męki, duszę napełniamy łaską i otrzymujemy zadatek przyszłej chwały."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "", "x": "Wielbię Ciebie w każdym momencie, o żywy Chlebie nasz, w tym Sakramencie."}, {"t": "r", "x": "Można zaśpiewać zwrotkę pieśni eucharystycznej."}]'::jsonb),
('zwykly', 3, 'Obrzędy wstępne', 'Akt pokuty', '[{"t": "r", "x": "Szafarz wzywa chorego i obecnych do wzbudzenia żalu za grzechy:"}, {"t": "l", "w": "S", "x": "Uznajmy przed Bogiem, że jesteśmy grzeszni, abyśmy mogli godnie uczestniczyć w obrzędzie Komunii św."}, {"t": "r", "x": "Następuje krótkie milczenie."}, {"t": "r", "x": "Wszyscy razem odmawiają spowiedź powszechną:"}, {"t": "l", "w": "W", "x": "Spowiadam się Bogu wszechmogącemu i wam, bracia i siostry, że bardzo zgrzeszyłem myślą, mową, uczynkiem i zaniedbaniem; moja wina, moja wina, moja bardzo wielka wina. Przeto błagam Najświętszą Maryję, zawsze Dziewicę, wszystkich Aniołów i Świętych, i was, bracia i siostry, o modlitwę za mnie do Pana, Boga naszego."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Zmiłuj się nad nami, Panie."}, {"t": "l", "w": "W", "x": "Bo zgrzeszyliśmy przeciw Tobie."}, {"t": "l", "w": "S", "x": "Okaż nam, Panie, miłosierdzie swoje."}, {"t": "l", "w": "W", "x": "I daj nam swoje zbawienie."}, {"t": "alt", "x": "Albo:"}, {"t": "r", "x": "Szafarz lub ktoś inny z obecnych wypowiada następujące lub podobne wezwania:"}, {"t": "l", "w": "S", "x": "Panie, który przez tajemnicę swojej śmierci i zmartwychwstania dokonałeś naszego zbawienia, zmiłuj się nad nami."}, {"t": "l", "w": "W", "x": "Zmiłuj się nad nami."}, {"t": "l", "w": "S", "x": "Chryste, który przez nasze cierpienia odnawiasz cudowne dzieła swojej męki, zmiłuj się nad nami."}, {"t": "l", "w": "W", "x": "Zmiłuj się nad nami."}, {"t": "l", "w": "S", "x": "Panie, który przez przyjęcie Twojego Ciała czynisz nas uczestnikami swojej ofiary paschalnej, zmiłuj się nad nami."}, {"t": "l", "w": "W", "x": "Zmiłuj się nad nami."}, {"t": "r", "x": "Szafarz kończy:"}, {"t": "l", "w": "S", "x": "Niech się zmiłuje nad nami Bóg wszechmogący i odpuściwszy nam grzechy, doprowadzi nas do życia wiecznego."}, {"t": "l", "w": "W", "x": "Amen."}]'::jsonb),
('zwykly', 4, 'Czytanie Słowa Bożego', 'Czytanie Słowa Bożego', '[{"t": "r", "x": "Następnie, zależnie od okoliczności, ktoś z obecnych lub sam szafarz może odczytać tekst Pisma św., np.:"}, {"t": "ref", "x": "J 6,54-55:"}, {"t": "l", "w": "", "x": "Kto spożywa moje Ciało i pije moją Krew, ma życie wieczne, a Ja go wskrzeszę w dniu ostatecznym. Ciało moje jest prawdziwym pokarmem, a Krew moja jest prawdziwym napojem. Kto spożywa moje Ciało i Krew moją pije, trwa we Mnie, a Ja w nim. Jak Mnie posłał żyjący Ojciec, a Ja żyję przez Ojca, tak i ten, kto Mnie spożywa, będzie żył przeze Mnie. To jest chleb, który z nieba zstąpił - nie jest on taki, jak ten, który jedli wasi przodkowie, a poumierali. Kto spożywa ten chleb, będzie żył na wieki."}, {"t": "ref", "x": "J 14,6:"}, {"t": "l", "w": "", "x": "Ja jestem drogą i prawdą, i życiem. Nikt nie przychodzi do Ojca inaczej, jak tylko przeze Mnie."}, {"t": "ref", "x": "J 14,23:"}, {"t": "l", "w": "", "x": "Jeżeli Mnie kto miłuje, będzie zachowywał moją naukę, a Ojciec mój umiłuje go i przyjdziemy do niego i będziemy u niego przebywać."}, {"t": "ref", "x": "J 15,4:"}, {"t": "l", "w": "", "x": "Wy trwajcie we Mnie, a Ja będę trwał w was. Podobnie jak latorośl nie może przynosić owocu sama z siebie, jeśli nie trwa w winnym krzewie, tak samo i wy, jeżeli we Mnie trwać nie będziecie."}, {"t": "ref", "x": "1 Kor 11,26:"}, {"t": "l", "w": "", "x": "Ilekroć spożywacie ten chleb albo pijecie kielich, śmierć Pańską głosicie, aż przyjdzie."}]'::jsonb),
('zwykly', 5, 'Modlitwa Pańska', 'Modlitwa Pańska', '[{"t": "r", "x": "Szafarz zachęca do Modlitwy Pańskiej tymi lub podobnymi słowami:"}, {"t": "l", "w": "S", "x": "Módlmy się wspólnie do Boga, jak nas nauczył nasz Zbawiciel, Jezus Chrystus."}, {"t": "r", "x": "Wszyscy odmawiają:"}, {"t": "l", "w": "W", "x": "Ojcze nasz, któryś jest w niebie, święć się imię Twoje, przyjdź królestwo Twoje, bądź wola Twoja jako w niebie, tak i na ziemi. Chleba naszego powszedniego daj nam dzisiaj, i odpuść nam nasze winy, jako i my odpuszczamy naszym winowajcom. I nie wódź nas na pokuszenie, ale nas zbaw ode złego."}]'::jsonb),
('zwykly', 6, 'Komunia Święta', 'Komunia Święta', '[{"t": "r", "x": "Szafarz ukazuje Najświętszy Sakrament i mówi:"}, {"t": "l", "w": "S", "x": "Oto Baranek Boży, który gładzi grzechy świata. Błogosławieni, którzy zostali wezwani na Jego ucztę."}, {"t": "r", "x": "Chory i inni mający przyjąć Komunię św. mówią:"}, {"t": "l", "w": "P", "x": "Panie, nie jestem godzien, abyś przyszedł do mnie, ale powiedz tylko słowo, a będzie uzdrowiona dusza moja."}, {"t": "r", "x": "Szafarz podchodzi do chorego i ukazując mu Najświętszy Sakrament mówi:"}, {"t": "l", "w": "S", "x": "Ciało Chrystusa."}, {"t": "l", "w": "Ch", "x": "Amen."}, {"t": "r", "x": "Następnie przyjmuje Komunię św."}, {"t": "r", "x": "Obecni, którzy pragną przyjąć Komunię św., przyjmują Najświętszy Sakrament w zwykły sposób."}]'::jsonb),
('zwykly', 7, 'Zakończenie obrzędu', 'Zakończenie obrzędu', '[{"t": "r", "x": "Po rozdzieleniu Komunii św. szafarz oczyszcza naczynie i umywa palce. Stosownie do okoliczności można przez chwilę zachować święte milczenie."}, {"t": "r", "x": "Następnie szafarz odmawia modlitwę końcową:"}, {"t": "l", "w": "S", "x": "Módlmy się."}, {"t": "l", "w": "S", "x": "Panie, Ojcze Święty, wszechmogący, wieczny Boże, z ufności Cię prosimy, aby Najświętsze Ciało Twojego Syna, Jezusa Chrystusa, które przyjął nasz brat (przyjęła nasza siostra), było trwałą pomocą dla jego (jej) duszy i ciała. Przez Chrystusa, Pana naszego."}, {"t": "l", "w": "W", "x": "Amen."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Boże, nasz Ojcze, przez paschalne misterium swojego Syna dokonałeś naszego odkupienia, dlatego w sakramentalnych znakach głosimy śmierć i zmartwychwstanie Chrystusa, spraw, abyśmy stale doznawali wzrostu Twojej łaski. Przez Chrystusa, Pana naszego."}, {"t": "l", "w": "W", "x": "Amen."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Boże, Ty pozwalasz nam spożywać jeden chleb eucharystyczny i pić z jednego kielicha, prosimy Cię, daj nam prowadzić takie życie, abyśmy zjednoczeni w Chrystusie, z radością przyczyniali się do zbawienia świata. Przez Chrystusa, Pana naszego."}, {"t": "l", "w": "W", "x": "Amen."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Posileni świętym darem, dzięki Ci składamy, dobry Ojcze, i błagamy, aby moc Ducha Świętego, której nam udzieliłeś w Eucharystii, trwała w nas i przemieniała nasze życie. Przez Chrystusa, Pana naszego."}, {"t": "l", "w": "W", "x": "Amen."}]'::jsonb),
('zwykly', 8, 'Błogosławieństwo', 'Błogosławieństwo', '[{"t": "r", "x": "Szafarz wzywając błogosławieństwa Bożego i czyniąc znak krzyża na sobie mówi:"}, {"t": "l", "w": "S", "x": "Niech Bóg nas błogosławi, broni od wszelkiego zła i doprowadzi do życia wiecznego"}, {"t": "l", "w": "W", "x": "Amen."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Niech nas błogosławi i strzeże Bóg wszechmogący i miłosierny, Ojciec i Syn, + i Duch Święty."}, {"t": "l", "w": "W", "x": "Amen."}]'::jsonb);
INSERT INTO sz_obrzedy (id, kolejnosc, zakladka, skrot, tytul, wstep) VALUES ('skrocony', 2, 'Skrócony obrzęd', 'Skrócony', 'Skrócony obrzęd Komunii Chorych udzielanej przez nadzwyczajnego szafarza', 'Obrzęd skrócony stosuje się wtedy, gdy trzeba udzielić Komunii św. wielu chorym, znajdującym się w różnych pokojach tego samego domu, : np. tego samego szpitala. Można włączyć pewne elementy obrzędu zwyczajnego.');
INSERT INTO sz_obrzedy_kroki (obrzed_id, nr, sekcja, tytul, bloki) VALUES
('skrocony', 1, '', 'Antyfona', '[{"t": "r", "x": "Obrzęd można rozpocząć w kościele, w kaplicy albo w pierwszym pomieszczeniu odmówieniem przez szafarza antyfony:"}, {"t": "l", "w": "S", "x": "O święta Uczto,na której przyjmujemy Chrystusa, odnawiamy pamięć Jego męki, duszę napełniamy łaską i otrzymujemy zadatek przyszłej chwały."}]'::jsonb),
('skrocony', 2, '', 'Komunia Święta', '[{"t": "r", "x": "Następnie szafarz udaje się do chorych, o ile to możliwe, w towarzystwie jakiejś osoby ze świecą. Szafarz mówi, albo raz do wszystkich chorych, którzy są w jednym pokoju, albo do każdego przyjmującego Komunię św.:"}, {"t": "l", "w": "S", "x": "Oto Baranek Boży, który gładzi grzechy świata.\nBłogosławieni, którzy zostali wezwani na Jego ucztę."}, {"t": "r", "x": "Przyjmujący Komunię św. mówią:"}, {"t": "l", "w": "P", "x": "Panie, nie jestem godzien, abyś przyszedł do mnie, ale powiedz tylko słowo, a będzie uzdrowiona dusza moja."}, {"t": "r", "x": "Chorzy przyjmują Komunię św. w zwykły sposób."}]'::jsonb),
('skrocony', 3, '', 'Modlitwa końcowa', '[{"t": "r", "x": "Końcową modlitwę można odmówić w kościele, w kaplicy albo w ostatnim pomieszczeniu."}]'::jsonb);
INSERT INTO sz_obrzedy (id, kolejnosc, zakladka, skrot, tytul, wstep) VALUES ('wiatyk', 3, 'Wiatyk', 'Wiatyk', 'Wiatyk udzielany przez nadzwyczajnego szafarza', '');
INSERT INTO sz_obrzedy_kroki (obrzed_id, nr, sekcja, tytul, bloki) VALUES
('wiatyk', 1, 'Obrzędy wstępne', 'Pozdrowienie', '[{"t": "l", "w": "S", "x": "Niech będzie pochwalony Jezus Chrystus."}, {"t": "l", "w": "W", "x": "Na wieki wieków. Amen."}]'::jsonb),
('wiatyk', 2, 'Obrzędy wstępne', 'Adoracja', '[{"t": "r", "x": "Następnie szafarz składa Najświętszy Sakrament na stole i adoruje Go razem z obecnymi w ciszy albo odmawiając odpowiednią modlitwę, np.:"}, {"t": "l", "w": "", "x": "O święta Uczto,\nna której przyjmujemy Chrystusa,\nodnawiamy pamięć Jego męki,\nduszę napełniamy łaską\ni otrzymujemy zadatek przyszłej chwały."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "", "x": "Wielbię Ciebie w każdym momencie,\no żywy Chlebie nasz, w tym Sakramencie."}, {"t": "r", "x": "Można zaśpiewać zwrotkę pieśni eucharystycznej."}]'::jsonb),
('wiatyk', 3, 'Obrzędy wstępne', 'Pouczenie', '[{"t": "r", "x": "Szafarz zwraca się do obecnych z następującym pouczeniem. Może je lepiej dostosować do sytuacji chorego."}, {"t": "l", "w": "S", "x": "Drodzy bracia i siostry, nasz Zbawiciel Jezus Chrystus, zanim odszedł z tego świata do Ojca, zostawił nam Sakrament swojego Ciała i Krwi. W godzinie naszego przejścia z tego życia do Boga otrzymujemy Ciało i Krew Chrystusa jako pokarm na drogą i zadatek zmartwychwstania. Zjednoczeni w miłości z naszym bratem (naszą siostrą), módlmy się za niego (nią)."}, {"t": "r", "x": "Wszyscy przez chwilę modlą się w ciszy."}]'::jsonb),
('wiatyk', 4, 'Obrzędy wstępne', 'Akt pokuty', '[{"t": "r", "x": "Szafarz wzywa chorego i obecnych do wzbudzenia żalu za grzechy:"}, {"t": "l", "w": "S", "x": "Uznajmy, że jesteśmy grzeszni, abyśmy mogli godnie uczestniczyć w obrzędach Komunii św."}, {"t": "r", "x": "Następuje krótkie milczenie. Wszyscy razem odmawiają spowiedź powszechną:"}, {"t": "l", "w": "W", "x": "Spowiadam się Bogu wszechmogącemu i wam, bracia i siostry, że bardzo zgrzeszyłem myślą, mowa, uczynkiem i zaniedbaniem: moja wina, moja wina, moja bardzo wielka wina. Przeto błagam Najświętszą Maryję, zawsze Dziewicę, wszystkich Aniołów i Świętych, i was, bracia i siostry, o modlitwę za mnie do Pana, Boga naszego."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Zmiłuj się nad nami, Panie."}, {"t": "l", "w": "W", "x": "Bo zgrzeszyliśmy przeciw Tobie."}, {"t": "l", "w": "S", "x": "Okaż nam, Panie, miłosierdzie swoje."}, {"t": "l", "w": "W", "x": "I daj nam swoje zbawienie."}]'::jsonb),
('wiatyk', 5, 'Czytanie Słowa Bożego', 'Czytanie Słowa Bożego', '[{"t": "r", "x": "Następnie, zależnie od okoliczności, ktoś z obecnych lub sam szafarz może odczytać odpowiedni tekst Pisma św."}]'::jsonb),
('wiatyk', 6, 'Odnowienie chrzcielnego wyznania wiary', 'Odnowienie chrzcielnego wyznania wiary', '[{"t": "r", "x": "Wypada, aby chory, zanim przyjmie Wiatyk, odnowił chrzcielne wyznanie wiary. Szafarz powinien je poprzedzić krótkim wprowadzeniem, np.:"}, {"t": "l", "w": "S", "x": "Bracie (Siostro), w ważnych chwilach naszego życia odnawiamy wiarę, która nas łączy z Bogiem od naszego chrztu. Aby, wyznać wiarę, odpowiadaj na moje pytania."}, {"t": "l", "w": "S", "x": "Czy wierzysz w Boga Ojca wszechmogącego, Stworzyciela nieba i ziemi?"}, {"t": "l", "w": "Ch", "x": "Wierzę."}, {"t": "l", "w": "S", "x": "Czy wierzysz w Jezusa Chrystusa, Jego Syna, Pana naszego, narodzonego z Maryi Dziewicy, umęczonego i pogrzebanego, który powstał z martwych i zasiada po prawicy Ojca?"}, {"t": "l", "w": "Ch", "x": "Wierzę."}, {"t": "l", "w": "S", "x": "Czy wierzysz w Ducha Świętego, święty Kościół powszechny, Świętych obcowanie, grzechów odpuszczenie, zmartwychwstanie ciała i życie wieczne?"}, {"t": "l", "w": "Ch", "x": "Wierzę."}]'::jsonb),
('wiatyk', 7, 'Litania za chorego', 'Litania za chorego', '[{"t": "r", "x": "Jeżeli stan chorego na to pozwala, odmawia się krótką litanię. Na wezwania odpowiada chory w miarę swoich sił oraz obecni. Można się posłużyć podanymi wezwaniami lub podobnymi."}, {"t": "l", "w": "S", "x": "Zjednoczeni we wspólnocie Kościoła wzywajmy Jezusa Chrystusa i wołajmy do Niego: Chryste, wysłuchaj nas."}, {"t": "l", "w": "W", "x": "Chryste, wysłuchaj nas."}, {"t": "l", "w": "S", "x": "Panie Jezu, Ty umiłowałeś nas do końca i wydałeś się na śmierć, aby dać nam życię, błagamy Cię za naszego brata (naszą siostrę)."}, {"t": "l", "w": "W", "x": "Chryste, wysłuchaj nas."}, {"t": "l", "w": "S", "x": "Panie, Ty powiedziałeś: „Kto spożywa moje ciało i pije moją krew, ma życie wieczne\", błagamy Cię za naszego brata (naszą siostrę)."}, {"t": "l", "w": "W", "x": "Chryste, wysłuchaj nas."}, {"t": "l", "w": "S", "x": "Panie, Ty zapraszasz nas na ucztę w niebie, na której nie będzie już więcej ani bólu, ani żałoby, ani smutku, ani rozłąki, błagamy Cię za naszego brata (naszą siostrę)."}, {"t": "l", "w": "W", "x": "Chryste, wysłuchaj nas."}]'::jsonb),
('wiatyk', 8, 'Modlitwa Pańska', 'Modlitwa Pańska', '[{"t": "r", "x": "Szafarz wprowadza do Modlitwy Pańskiej tymi lub podobnymi słowami:"}, {"t": "l", "w": "S", "x": "Módlmy się wspólnie do Boga, jak nas nauczył nasz Zbawiciel, Jezus Chrystus."}, {"t": "r", "x": "Wszyscy razem mówią:"}, {"t": "l", "w": "W", "x": "Ojcze nasz, któryś jest w niebie, święć się imię Twoje, przyjdź królestwo Twoje, bądź wola Twoja jako w niebie, tak i na ziemi. Chleba naszego powszedniego daj nam dzisiaj, i odpuść nam nasze winy, jako i my odpuszczamy naszym winowajcom. I nie wódź nas na pokuszenie, ale nas zbaw ode złego."}]'::jsonb),
('wiatyk', 9, 'Wiatyk', 'Wiatyk', '[{"t": "r", "x": "Szafarz ukazuje Najświętszy Sakrament i mówi:"}, {"t": "l", "w": "S", "x": "Oto Baranek Boży, który gładzi grzechy świata. Błogosławieni, którzy zostali wezwani na Jego ucztę."}, {"t": "r", "x": "Chory, jeśli może, i inni mający przyjąć Komunię św. mówią:"}, {"t": "l", "w": "P", "x": "Panie, nie jestem godzien, abyś przyszedł do mnie, ale powiedz tylko słowo, a będzie uzdrowiona dusza moja."}, {"t": "r", "x": "Szafarz podchodzi do chorego i ukazując mu Najświętszy Sakrament mówi:"}, {"t": "l", "w": "S", "x": "Ciało Chrystusa."}, {"t": "l", "w": "Ch", "x": "Amen."}, {"t": "r", "x": "Natychmiast szafarz dodaje:"}, {"t": "l", "w": "S", "x": "Niech Chrystus cię strzeże i zaprowadzi do życia wiecznego."}, {"t": "l", "w": "Ch", "x": "Amen."}, {"t": "r", "x": "Obecni, którzy pragną przyjąć Komunię św., przyjmują Najświętszy Sakrament w zwykły sposób."}, {"t": "r", "x": "Po rozdzieleniu Komunii św. szafarz dokonuje puryfikacji. Stosownie do okoliczności można przez chwilę zachować święte milczenie."}]'::jsonb),
('wiatyk', 10, 'Zakończenie obrzędu', 'Zakończenie obrzędu', '[{"t": "r", "x": "Szafarz odmawia końcową modlitwę:"}, {"t": "l", "w": "S", "x": "Módlmy się."}, {"t": "l", "w": "S", "x": "Boże, Twój Syn jest dla nas drogą, prawdą i życiem, wejrzyj litościwie na swojego sługę N, który (swoją służebnicę N, która) ufa Twoim obietnicom, i spraw, aby pokrzepiony(a) Ciałem i Krwią Twojego Syna, w pokoju przeszedł (przeszła) do Twojego Królestwa. Przez Chrystusa, Pana naszego. Amen."}, {"t": "alt", "x": "Albo:"}, {"t": "l", "w": "S", "x": "Boże, Ty dla swoich wiernych jesteś wiecznym zbawieniem, spraw, aby Twój sługa N. pokrzepiony (Twoja służebnica, pokrzepiona) Ciałem i Krwią Twojego Syna, przeszedł (przeszła) bezpiecznie do Królestwa światłości i życia. Przez Chrystusa, Pana naszego. Amen."}, {"t": "r", "x": "Szafarz mówi:"}, {"t": "l", "w": "S", "x": "Niech Bóg zawsze będzie z tobą, broni cię swoją mocą i zachowa w pokoju."}, {"t": "l", "w": "W", "x": "Amen."}, {"t": "r", "x": "Na końcu szafarz i obecni mogą przekazać choremu znak pokoju."}]'::jsonb);
INSERT INTO sz_ustawienia (klucz, wartosc) VALUES
('kancelaria_adres', 'ul. ks. Tischnera 50, 43-100 Tychy'),
('kancelaria_telefon', '32 217 50 30'),
('opiekun', 'ks. Grzegorz Kolbiarz'),
('lider', 'Paweł Pełka'),
('spotkania_termin', 'Środa, 19:00'),
('spotkania_miejsce', 'Kaplica św. Józefa'),
('wspolnota_wstep', 'Jesteśmy świeckimi wiernymi parafii bł. Karoliny Kózkówny, którzy z upoważnienia biskupa pomagają kapłanom w udzielaniu Komunii Świętej – przy ołtarzu i w domach osób chorych.'),
('wspolnota_opis', 'W każdą niedzielę czterech z nas zanosi Komunię Świętą chorym na osiedlach W, T2, U i NO. Przydział zmienia się co tydzień według stałej kolejki, tak aby każdy szafarz poznał chorych z różnych części parafii. W dni powszednie pełnimy posługę przy ołtarzu podczas wieczornych Mszy Świętych.
